      if (this.deleting || submit.hasAttribute("disabled")) {
        return;
      }
      this.deleting = true;
      submit.setAttribute("disabled", "");
      const basePath = this.getAttribute("base-path") ?? "";
      const id2 = this.getAttribute("page-id") ?? "";
