  class CmsConfirmForm extends HTMLElement {
    _busy = false;
    _onClick = async (e) => {
      const triggerSelector = this.getAttribute("trigger-selector") || "p9r-button, p9r-action-menu-item, button";
      const trigger = e.target.closest(triggerSelector);
      if (!trigger || !this.contains(trigger)) {
        return;
      }
      e.preventDefault();
      e.stopImmediatePropagation();
      if (this._busy) {
        return;
      }
      const message = this.getAttribute("message") || "Are you sure?";
      if (!confirm(message)) {
        return;
      }
      this._busy = true;
      try {
        await this._submit(false);
      } finally {
        this._busy = false;
      }
    };
    connectedCallback() {
      this.addEventListener("click", this._onClick, true);
    }
    disconnectedCallback() {
      this.removeEventListener("click", this._onClick, true);
    }
    async _submit(force) {
      const target = this.getAttribute("target");
      const method = this.getAttribute("method") || "POST";
      if (!target) {
        kb("cms-confirm-form: missing target", { type: "error" });
        return;
      }
      const url = force ? withForce(target) : target;
      let res;
      try {
        res = await fetch(url, { method });
      } catch (e) {
        kb(`Request failed: ${e instanceof Error ? e.message : String(e)}`, { type: "error" });
        return;
      }
      if (res.ok) {
        this._onSuccess();
        return;
      }
      if (res.status === 409 && !force) {
        const body = await res.json().catch(() => ({}));
        const followUp = formatConflict(body);
        const followMessage = this.getAttribute("conflict-confirm-message") || "Proceed anyway?";
        if (confirm(`${body.error ?? "Conflict"}

${followUp}

${followMessage}`)) {
          await this._submit(true);
        }
        return;
      }
      const text = await res.text().catch(() => "");
      let message = text;
      try {
        const body = JSON.parse(text);
        if (body?.error) {
          message = body.error;
        }
      } catch {}
      kb(message || `HTTP ${res.status}`, { type: "error" });
    }
    _onSuccess() {
      const emit = this.getAttribute("emit");
      if (emit) {
        document.dispatchEvent(new BubblesEvent(emit));
      }
      const redirect = this.getAttribute("redirect");
      if (redirect) {
        window.location.href = redirect;
      }
    }
  }
  function withForce(target) {
    return target + (target.includes("?") ? "&" : "?") + "force=true";
  }
  function formatConflict(body) {
    const lines = [];
    const pages = Array.isArray(body?.pages) ? body.pages : [];
    if (pages.length) {
      lines.push("Pages:");
      for (const p3 of pages) {
        lines.push(`  • ${p3.title || p3.path}`);
      }
    }
    return lines.join(`
`);
  }
