  async function loadPageConfig(shell, pageId) {
    const response = await fetch(`${getMetaBasePath()}/api/page/configDetail?id=${encodeURIComponent(pageId)}`);
    if (response.redirected) {
      window.location.href = response.url;
      return;
    }
    if (!response.ok) {
      shell.setSaveStatus("Page load failed");
      return;
    }
    const page = await response.json();
    shell.setPageConfig({
      id: page.id,
      title: page.title,
      path: page.path,
      description: page.description,
      tags: page.tags,
      published: page.published
    });
  }

  // src/components/editorSystemV2/documentMutations.ts
  async function saveDocument(page, content) {
    const response = await fetch(`${getMetaBasePath()}/api/page/content`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        id: page.id,
        content
      })
    });
    if (!response.ok) {
      throw new Error(`Page save failed with ${response.status}`);
    }
  }

